import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Qvwhmedc.js";var i=JSON.parse(`{"title":"Writing Permanent Content","description":"","frontmatter":{"title":"Writing Permanent Content"},"headers":[],"relativePath":"guides/contributing/writing-documentation/writing-permanent-content.md","filePath":"guides/contributing/writing-documentation/writing-permanent-content.md"}`),a={name:`guides/contributing/writing-documentation/writing-permanent-content.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="writing-permanent-content" tabindex="-1">Writing Permanent Content <a class="header-anchor" href="#writing-permanent-content" aria-label="Permalink to “Writing Permanent Content”">​</a></h1><p><a href="/pr-preview/pr-11154/upgrading/">Upgrading</a> and <a href="/pr-preview/pr-11154/blog/">Blog</a> are different from the rest of the guides: they hold point-in-time content whose URLs are a permanent contract with readers, not just the current best explanation of a concept. Follow these rules when adding to either section.</p><h2 id="urls-are-never-renamed-or-unpublished" tabindex="-1">URLs are never renamed or unpublished <a class="header-anchor" href="#urls-are-never-renamed-or-unpublished" aria-label="Permalink to “URLs are never renamed or unpublished”">​</a></h2><p>Once a page under <code>upgrading/</code> or <code>blog/</code> is published, its path doesn&#39;t change and the page is never deleted, even after its content is out of date.</p><p>If a page&#39;s content is fully superseded (a newer major-version guide replaces it, a post is factually wrong, etc.), don&#39;t delete or move it. Instead:</p><ol><li><p>Replace its body with a short pointer to the replacement, wrapped in a <code>:::danger</code> callout, e.g.:</p><div class="language-md"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">draft</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::danger </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**We&#39;ve moved!**</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">This guide has [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">moved</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">/upgrading/v6/index.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span></code></pre></div></li><li><p>Set <code>draft: true</code> in its frontmatter. This hides the page from the sidebar and nav (so it doesn&#39;t clutter navigation for current readers) while leaving the page itself published at its original URL — unlike the rest of the guides, content here is <strong>not</strong> removed by the sync step just because it&#39;s marked <code>draft</code>.</p></li></ol><h2 id="every-page-is-dated-and-versioned" tabindex="-1">Every page is dated and versioned <a class="header-anchor" href="#every-page-is-dated-and-versioned" aria-label="Permalink to “Every page is dated and versioned”">​</a></h2><p>Record the <strong><em>Warp</em>Drive</strong>* version (and the date) a page was written for, usually as a <code>&lt;SinceBadge version=&quot;X.Y.Z&quot; /&gt;</code> near the top of the page next to the date it was authored or last meaningfully revised. This lets a reader who lands on an old search result or bookmark know immediately whether the page still applies to the version they&#39;re using.</p><h2 id="organize-by-major-version" tabindex="-1">Organize by major version <a class="header-anchor" href="#organize-by-major-version" aria-label="Permalink to “Organize by major version”">​</a></h2><p>Each section is sub-divided by major version (<code>upgrading/v5/</code>, <code>blog/v5/</code>, <code>upgrading/v6/</code>, ...). Within a major version&#39;s directory:</p><ul><li><code>upgrading/&lt;major&gt;/</code> holds that version&#39;s upgrade guide plus any deprecation or feature-specific migration guides written against it.</li><li><code>blog/&lt;major&gt;/</code> holds posts published while that major version was current.</li></ul><p>Add new major-version directories to the section&#39;s root <code>_meta.json</code> <code>items</code> list so they sort in release order rather than alphabetically.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};